//! Cross-language golden-frame and adversarial decoding tests.
//!
//! `spec/fixtures/` is generated by `crates/hfdrive-protocol/tools/gen-fixtures.js`
//! and shared with the C# `HfDrive.Protocol.Tests` project. Both codecs must
//! parse every golden frame and reproduce its payload bytes byte-for-byte,
//! and must reject every invalid frame with the listed error code.

use std::future::Future;
use std::path::PathBuf;

use hfdrive_protocol::{read_frame, Body, Envelope, EnvelopeKind, ProtocolCodecError, Request};

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../spec/fixtures")
}

fn hex_decode(text: &str) -> Vec<u8> {
    assert!(text.len() % 2 == 0, "odd hex length");
    (0..text.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&text[index..index + 2], 16).expect("valid hex"))
        .collect()
}

/// Maps a codec error to the wire error code string the fixtures expect.
fn error_code(error: &ProtocolCodecError) -> String {
    error.to_protocol_error().code.wire().to_string()
}

struct GoldenFixture {
    name: String,
    expectation: serde_json::Value,
    frame: Vec<u8>,
    payload: Vec<u8>,
    envelope: serde_json::Value,
}

fn load_golden(path: &std::path::Path) -> GoldenFixture {
    let text = std::fs::read_to_string(path).expect("read golden fixture");
    let value: serde_json::Value = serde_json::from_str(&text).expect("parse golden fixture");
    let frame = hex_decode(value["frame_hex"].as_str().expect("frame_hex"));
    let payload = hex_decode(value["payload_hex"].as_str().expect("payload_hex"));
    GoldenFixture {
        name: value["name"].as_str().expect("name").to_string(),
        expectation: value["expectation"].clone(),
        frame,
        payload,
        envelope: value["envelope"].clone(),
    }
}

struct InvalidFixture {
    name: String,
    stage: String,
    expected_code: String,
    frame: Vec<u8>,
}

fn load_invalid(path: &std::path::Path) -> InvalidFixture {
    let text = std::fs::read_to_string(path).expect("read invalid fixture");
    let value: serde_json::Value = serde_json::from_str(&text).expect("parse invalid fixture");
    InvalidFixture {
        name: value["name"].as_str().expect("name").to_string(),
        stage: value["stage"].as_str().expect("stage").to_string(),
        expected_code: value["expectation"]["error_code"]
            .as_str()
            .expect("error_code")
            .to_string(),
        frame: hex_decode(value["frame_hex"].as_str().expect("frame_hex")),
    }
}

fn fixture_paths(subdir: &str) -> Vec<PathBuf> {
    let mut paths: Vec<PathBuf> = std::fs::read_dir(fixtures_dir().join(subdir))
        .expect("fixtures directory exists")
        .map(|entry| entry.expect("dir entry").path())
        .filter(|path| path.extension().is_some_and(|ext| ext == "json"))
        .collect();
    paths.sort();
    assert!(!paths.is_empty(), "no fixtures in {subdir}");
    paths
}

#[test]
fn golden_frames_decode_and_reencode_byte_identically() {
    for path in fixture_paths("golden") {
        let fixture = load_golden(&path);
        if fixture.expectation["parse"].as_str() != Some("accept") {
            // Fixtures with a non-accept expectation are covered by their own
            // test (e.g. the handshake-only hello from a future version).
            continue;
        }

        // Frame layer: header + payload delivered as stored.
        let mut source = fixture.frame.as_slice();
        let frame = futures_block_on(read_frame(&mut source))
            .expect("frame io")
            .expect("frame present");
        assert_eq!(frame, fixture.payload, "frame payload for {}", fixture.name);
        assert!(source.is_empty(), "frame fully consumed for {}", fixture.name);

        // Envelope layer: strict parse, then canonical re-encode must be
        // byte-identical to the golden payload.
        let envelope = Envelope::parse(&frame).unwrap_or_else(|error| {
            panic!("golden {} must parse, got {error}", fixture.name)
        });
        let reencoded = envelope
            .encode_canonical()
            .expect("canonical re-encode")
            .to_vec();
        assert_eq!(
            reencoded, fixture.payload,
            "canonical bytes for {}",
            fixture.name
        );

        // The decoded envelope agrees with the fixture's envelope fields.
        assert_eq!(
            envelope.kind,
            match fixture.envelope["kind"].as_str().unwrap() {
                "request" => EnvelopeKind::Request,
                "response" => EnvelopeKind::Response,
                "event" => EnvelopeKind::Event,
                other => panic!("unknown kind {other}"),
            }
        );
        assert_eq!(
            envelope.method,
            fixture.envelope["method"].as_str().unwrap(),
            "method for {}",
            fixture.name
        );

        if let Some(marker) = fixture.expectation["describe_for_log_must_not_contain"].as_str() {
            let description = envelope.describe_for_log();
            assert!(
                !description.contains(marker),
                "describe_for_log must not leak the protected secret ({})",
                fixture.name
            );
            let debug = format!("{envelope:?}");
            assert!(
                !debug.contains(marker),
                "Debug must not leak the protected secret ({})",
                fixture.name
            );
        }
    }
}

#[test]
fn golden_hello_from_future_version_uses_handshake_parse() {
    let path = fixtures_dir().join("golden/hello_request_from_v2.json");
    let fixture = load_golden(&path);
    let expectation = fixture.expectation["parse"].as_str().unwrap();
    assert_eq!(expectation, "reject:unsupported_protocol");
    match Envelope::parse(&fixture.payload) {
        Err(error) => assert_eq!(error_code(&error), "unsupported_protocol"),
        Ok(_) => panic!("strict parse must reject a foreign version"),
    }
    let envelope = Envelope::parse_handshake(&fixture.payload)
        .expect("handshake parse must accept a hello request");
    assert!(matches!(envelope.body, Body::Request(Request::Hello(_))));
    assert_eq!(
        fixture.expectation["parse_handshake"].as_str().unwrap(),
        "accept"
    );
}

#[test]
fn invalid_frames_reject_with_the_documented_error_code() {
    for path in fixture_paths("invalid") {
        let fixture = load_invalid(&path);
        let mut source = fixture.frame.as_slice();

        if fixture.stage == "frame" {
            match futures_block_on(read_frame(&mut source)) {
                Err(error) => assert_eq!(
                    error_code(&error),
                    fixture.expected_code,
                    "frame stage code for {}",
                    fixture.name
                ),
                Ok(_) => panic!("{} must fail at the frame stage", fixture.name),
            }
            continue;
        }

        // Envelope stage: the frame itself must be well-formed.
        let payload = futures_block_on(read_frame(&mut source))
            .expect("frame io")
            .unwrap_or_else(|| panic!("{} needs a complete frame", fixture.name));
        match Envelope::parse(&payload) {
            Err(error) => assert_eq!(
                error_code(&error),
                fixture.expected_code,
                "envelope stage code for {}",
                fixture.name
            ),
            Ok(_) => panic!("{} must be rejected", fixture.name),
        }
    }
}

/// Blocks on a future using a minimal current-thread runtime.
fn futures_block_on<F: Future>(future: F) -> F::Output {
    tokio::runtime::Builder::new_current_thread()
        .build()
        .expect("runtime")
        .block_on(future)
}

#[test]
fn every_wire_method_has_typed_request_and_result_variants() {
    // The fixture generator, the schema, and the typed enums must not drift:
    // the schema's body map must list exactly the typed method registry.
    let schema_text =
        std::fs::read_to_string(fixtures_dir().join("../ipc-v1.schema.json")).expect("read schema");
    let schema: serde_json::Value = serde_json::from_str(&schema_text).expect("parse schema");
    let listed: Vec<String> = schema["$defs"]["body_map"]["request_methods"]
        .as_array()
        .expect("request_methods array")
        .iter()
        .map(|item| item.as_str().unwrap().to_string())
        .collect();
    let mut registry: Vec<String> = hfdrive_protocol::ALL_METHODS
        .iter()
        .map(|method| method.to_string())
        .collect();
    registry.sort();
    assert_eq!(listed, registry, "schema and typed registry disagree");

    // Every golden request/response fixture names a method from the registry.
    for path in fixture_paths("golden") {
        let fixture = load_golden(&path);
        let method = fixture.envelope["method"].as_str().unwrap();
        if fixture.envelope["kind"].as_str() == Some("event") {
            assert!(
                matches!(method, "status_changed" | "activity_changed" | "conflicts_changed"),
                "unknown event {method}"
            );
        } else {
            assert!(
                registry.iter().any(|known| known == method),
                "method {method} missing from registry"
            );
        }
    }
}
